class Solution {
    public int maximumProduct(int[] nums) {
        int max1 = Integer.MIN_VALUE;
        int max2 = Integer.MIN_VALUE;
        int max3 = Integer.MIN_VALUE;
        int min1 = Integer.MAX_VALUE;
        int min2 = Integer.MAX_VALUE;

        for (int value : nums) {
            if (value > max1) {
                max3 = max2;
                max2 = max1;
                max1 = value;
            } else if (value > max2) {
                max3 = max2;
                max2 = value;
            } else if (value > max3) {
                max3 = value;
            }

            if (value < min1) {
                min2 = min1;
                min1 = value;
            } else if (value < min2) {
                min2 = value;
            }
        }

        return Math.max(max1 * max2 * max3, min1 * min2 * max1);
    }
}

import java.util.Arrays;

class Solution {
    public int maximumProduct(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        int threeLargest = nums[n - 1] * nums[n - 2] * nums[n - 3];
        int twoSmallestAndLargest = nums[0] * nums[1] * nums[n - 1];
        return Math.max(threeLargest, twoSmallestAndLargest);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

class Solution {
    public int maximumProduct(int[] nums) {
        PriorityQueue<Integer> largest = new PriorityQueue<>();
        PriorityQueue<Integer> smallest = new PriorityQueue<>(Collections.reverseOrder());

        for (int value : nums) {
            largest.offer(value);
            if (largest.size() > 3) {
                largest.poll();
            }
            smallest.offer(value);
            if (smallest.size() > 2) {
                smallest.poll();
            }
        }

        List<Integer> hi = new ArrayList<>(largest);
        List<Integer> lo = new ArrayList<>(smallest);
        Collections.sort(hi);
        Collections.sort(lo);
        int threeLargest = hi.get(0) * hi.get(1) * hi.get(2);
        int twoSmallestAndLargest = lo.get(0) * lo.get(1) * hi.get(2);
        return Math.max(threeLargest, twoSmallestAndLargest);
    }
}

class Solution {
    public int maximumProduct(int[] nums) {
        int[] counts = new int[2001];
        for (int value : nums) {
            counts[value + 1000]++;
        }

        int[] largest = new int[3];
        int hi = 0;
        for (int value = 1000; value >= -1000 && hi < 3; value--) {
            int repeat = counts[value + 1000];
            while (repeat > 0 && hi < 3) {
                largest[hi++] = value;
                repeat--;
            }
        }

        int[] smallest = new int[2];
        int lo = 0;
        for (int value = -1000; value <= 1000 && lo < 2; value++) {
            int repeat = counts[value + 1000];
            while (repeat > 0 && lo < 2) {
                smallest[lo++] = value;
                repeat--;
            }
        }

        int threeLargest = largest[0] * largest[1] * largest[2];
        int twoSmallestAndLargest = smallest[0] * smallest[1] * largest[0];
        return Math.max(threeLargest, twoSmallestAndLargest);
    }
}

import java.util.Arrays;

class Solution {
    public int maximumProduct(int[] nums) {
        long negInf = Long.MIN_VALUE / 4;
        long posInf = Long.MAX_VALUE / 4;
        long[] best = new long[4];
        long[] worst = new long[4];
        Arrays.fill(best, negInf);
        Arrays.fill(worst, posInf);
        best[0] = 1;
        worst[0] = 1;

        for (int value : nums) {
            for (int picks = 3; picks >= 1; picks--) {
                if (best[picks - 1] == negInf) {
                    continue;
                }
                long fromBest = best[picks - 1] * value;
                long fromWorst = worst[picks - 1] * value;
                best[picks] = Math.max(best[picks], Math.max(fromBest, fromWorst));
                worst[picks] = Math.min(worst[picks], Math.min(fromBest, fromWorst));
            }
        }

        return (int) best[3];
    }
}
